import { useMemo, useState } from "react";
import { Link, useNavigate, useParams } from "react-router-dom";
import {
  Activity, AlertCircle, ArrowLeft, ArrowRight, BarChart3, Bell, BookOpen,
  Building2, CalendarDays, Check, CheckCircle2, ChevronDown, ChevronLeft,
  ChevronRight, ClipboardCheck, ClipboardList, Clock3, Download, FileBarChart,
  FileCheck2, FileText, Filter, GraduationCap, LayoutDashboard, LockKeyhole,
  Mail, Menu, MessageSquare, MoreHorizontal, Pencil, Plus, RefreshCw, Search,
  Settings, ShieldCheck, SlidersHorizontal, Sparkles, Trash2, Upload, UserCheck,
  UserCog, UserPlus, Users, X,
} from "lucide-react";
import logo from "@/assets/website-logo.png";
import { adminStudents, adminFaculty, departments, courses, subjects, batches, assignments, exams, contentItems, approvals, auditLogs } from "@/data/adminPortalMockData";

type IconType = typeof LayoutDashboard;
type Row = Record<string, string | number>;
const navGroups: { label:string; items:{key:string;label:string;icon:IconType;badge?:string}[] }[] = [
  { label:"Dashboard", items:[{key:"overview",label:"Overview",icon:LayoutDashboard}] },
  { label:"Student management", items:[{key:"students",label:"All students",icon:Users},{key:"student-add",label:"Add student",icon:UserPlus},{key:"batches",label:"Groups / batches",icon:Building2},{key:"enrollments",label:"Enrollments",icon:ClipboardCheck}] },
  { label:"Faculty management", items:[{key:"faculty",label:"All faculty",icon:GraduationCap},{key:"faculty-add",label:"Add faculty",icon:UserPlus},{key:"faculty-activity",label:"Faculty workload",icon:Activity}] },
  { label:"Academics", items:[{key:"departments",label:"Departments",icon:Building2},{key:"courses",label:"Courses",icon:BookOpen},{key:"subjects",label:"Subjects",icon:FileText},{key:"timetable",label:"Timetable",icon:CalendarDays}] },
  { label:"Learning management", items:[{key:"content",label:"Learning content",icon:FileText},{key:"assignments",label:"Assignments",icon:ClipboardList},{key:"exams",label:"Exams",icon:FileCheck2},{key:"results",label:"Results",icon:BarChart3}] },
  { label:"Monitoring", items:[{key:"attendance",label:"Attendance",icon:UserCheck},{key:"student-progress",label:"Student progress",icon:Activity}] },
  { label:"Communication", items:[{key:"announcements",label:"Announcements",icon:MessageSquare},{key:"notifications",label:"Notifications",icon:Bell}] },
  { label:"Administration", items:[{key:"users",label:"User management",icon:Users},{key:"roles",label:"Roles & permissions",icon:ShieldCheck},{key:"approvals",label:"Requests / approvals",icon:ClipboardCheck,badge:"2"},{key:"reports",label:"Reports",icon:FileBarChart},{key:"analytics",label:"Analytics",icon:BarChart3},{key:"audit",label:"Activity logs",icon:Activity},{key:"settings",label:"Settings",icon:Settings}] },
];

const titles:Record<string,[string,string]> = {
  overview:["Administration overview","Institution-wide operations and LMS health"], students:["All students","Search, filter and manage every student account"], "student-add":["Add student","Create a new student record"], "student-profile":["Student profile","Complete academic and activity record"], faculty:["All faculty","Faculty directory, assignments and status"], "faculty-add":["Add faculty","Create a faculty account and teaching assignment"], "faculty-profile":["Faculty profile","Professional record and workload"], departments:["Departments","Academic structure and department ownership"], "department-details":["Department details","People, courses, subjects and batches"], courses:["Courses","Programs offered across the institution"], "course-details":["Course details","Students, faculty, content and performance"], subjects:["Subject management","Subjects, ownership and semester mapping"], batches:["Batch management","Classes, academic years and assigned faculty"], "batch-details":["Batch details","Roster, timetable, attendance and outcomes"], enrollments:["Enrollments","Student-to-course and batch allocation"], timetable:["Timetable","Institution-wide class scheduling"], content:["Learning content","Inspect and govern published LMS content"], assignments:["Assignments","Institution-wide assignment monitoring"], "assignment-details":["Assignment details","Submissions, marks and deadline status"], exams:["Exams","Examination planning and control"], "exam-details":["Exam details","Participation, results and performance"], results:["Results","Academic outcome analysis"], attendance:["Attendance dashboard","Daily and long-term attendance monitoring"], "student-progress":["Student progress","Completion, engagement and risk monitoring"], "faculty-activity":["Faculty activity","Workload and teaching engagement"], announcements:["Announcements","Institutional broadcast management"], notifications:["Notifications","Compose and review LMS notifications"], users:["User management","All LMS identities and account status"], roles:["Roles & permissions","Role-based access configuration"], approvals:["Requests & approvals","One queue for administrative decisions"], reports:["Reports center","Preview and export institutional reports"], analytics:["LMS analytics","Growth, engagement and performance intelligence"], audit:["Activity & audit log","Trace every important LMS action"], settings:["Administration settings","Institution, academic and notification configuration"], profile:["Administrator profile","Personal account and preferences"],
};

const Card=({children,className=""}:{children:React.ReactNode;className?:string})=><section className={`rounded-2xl border border-[#d8e8f2] bg-white shadow-[0_10px_30px_-24px_rgba(13,53,104,.4)] ${className}`}>{children}</section>;
const Status=({children}:{children:React.ReactNode})=>{const v=String(children).toLowerCase();const c=v.includes("active")||v.includes("published")||v.includes("approved")||v.includes("completed")||v.includes("ready")?"bg-emerald-50 text-emerald-700":v.includes("suspend")||v.includes("reject")||v.includes("failed")?"bg-red-50 text-red-700":v.includes("pending")||v.includes("upcoming")||v.includes("review")||v.includes("scheduled")?"bg-amber-50 text-amber-700":"bg-slate-100 text-slate-600";return <span className={`inline-flex rounded-full px-2.5 py-1 text-xs font-bold ${c}`}>{children}</span>};
const Primary=({children,onClick}:{children:React.ReactNode;onClick?:()=>void})=><button onClick={onClick} className="inline-flex items-center justify-center gap-2 rounded-xl bg-[#1555b6] px-4 py-2.5 text-sm font-bold text-white shadow-sm transition hover:-translate-y-0.5 hover:bg-[#0d438f]">{children}</button>;
const Secondary=({children,onClick}:{children:React.ReactNode;onClick?:()=>void})=><button onClick={onClick} className="inline-flex items-center justify-center gap-2 rounded-xl border border-slate-200 bg-white px-4 py-2.5 text-sm font-bold text-slate-700 hover:border-[#1555b6] hover:text-[#1555b6]">{children}</button>;
const Field=({label,placeholder,type="text",wide=false}:{label:string;placeholder:string;type?:string;wide?:boolean})=><label className={wide?"md:col-span-2":""}><span className="mb-2 block text-sm font-bold text-slate-700">{label} <i className="not-italic text-red-500">*</i></span>{type==="textarea"?<textarea rows={3} placeholder={placeholder} className="w-full rounded-xl border border-slate-200 bg-slate-50 p-3 text-sm outline-none focus:border-[#1555b6] focus:ring-4 focus:ring-blue-100"/>:<input type={type} placeholder={placeholder} className="h-12 w-full rounded-xl border border-slate-200 bg-slate-50 px-3 text-sm outline-none focus:border-[#1555b6] focus:ring-4 focus:ring-blue-100"/>}</label>;
const Progress=({value}:{value:number})=><div className="h-2 overflow-hidden rounded-full bg-slate-100"><div className={`h-full rounded-full ${value<70?"bg-amber-500":value>90?"bg-[#079a9d]":"bg-[#1555b6]"}`} style={{width:`${value}%`}}/></div>;

function Modal({title,children,onClose,action="Save"}:{title:string;children:React.ReactNode;onClose:()=>void;action?:string}){return <div className="fixed inset-0 z-[80] grid place-items-center bg-slate-950/45 p-4 backdrop-blur-sm"><div className="w-full max-w-lg rounded-3xl bg-white shadow-2xl"><div className="flex items-center justify-between border-b p-5"><h2 className="text-xl font-black text-[#0d3568]">{title}</h2><button onClick={onClose}><X/></button></div><div className="space-y-4 p-5">{children}</div><div className="flex justify-end gap-2 border-t p-5"><Secondary onClick={onClose}>Cancel</Secondary><Primary onClick={onClose}><Check className="h-4 w-4"/>{action}</Primary></div></div></div>}

function PageHead({eyebrow,title,copy,actions}:{eyebrow:string;title:string;copy:string;actions?:React.ReactNode}){return <div className="mb-6 flex flex-col justify-between gap-4 md:flex-row md:items-end"><div><p className="text-xs font-black uppercase tracking-[.18em] text-[#079a9d]">{eyebrow}</p><h2 className="mt-1 text-2xl font-black text-[#0d3568] lg:text-3xl">{title}</h2><p className="mt-2 text-sm text-slate-500">{copy}</p></div>{actions}</div>}
function StatGrid({items}:{items:[string,string,IconType,string?][]}){return <div className="grid gap-4 sm:grid-cols-2 xl:grid-cols-4">{items.map(([label,value,Icon,note])=><Card key={label} className="p-5"><div className="flex justify-between"><div><p className="text-sm font-semibold text-slate-500">{label}</p><p className="mt-2 text-3xl font-black text-[#0d3568]">{value}</p>{note&&<p className="mt-1 text-xs font-semibold text-[#079a9d]">{note}</p>}</div><span className="grid h-11 w-11 place-items-center rounded-xl bg-blue-50 text-[#1555b6]"><Icon className="h-5 w-5"/></span></div></Card>)}</div>}

function DataTable({rows,columns,onView,onDelete}:{rows:Row[];columns:[string,string][];onView?:()=>void;onDelete?:()=>void}){const [q,setQ]=useState("");const shown=useMemo(()=>rows.filter(r=>Object.values(r).join(" ").toLowerCase().includes(q.toLowerCase())),[rows,q]);return <Card><div className="flex flex-col gap-3 border-b p-4 lg:flex-row lg:items-center"><div className="relative max-w-md flex-1"><Search className="absolute left-3 top-1/2 h-4 w-4 -translate-y-1/2 text-slate-400"/><input value={q} onChange={e=>setQ(e.target.value)} placeholder="Search records…" className="h-11 w-full rounded-xl border border-slate-200 bg-slate-50 pl-10 pr-3 text-sm outline-none focus:border-[#1555b6]"/></div><div className="flex flex-wrap gap-2"><Secondary><Filter className="h-4 w-4"/>Filters</Secondary><Secondary><SlidersHorizontal className="h-4 w-4"/>Sort</Secondary><Secondary><Download className="h-4 w-4"/>Export</Secondary></div></div><div className="overflow-x-auto"><table className="w-full min-w-[900px] text-left"><thead className="bg-[#f5faff] text-[11px] uppercase tracking-wider text-slate-500"><tr><th className="px-4 py-3"><input type="checkbox"/></th>{columns.map(([key,label])=><th key={key} className="px-4 py-3 font-bold">{label}</th>)}<th className="px-4 py-3">Actions</th></tr></thead><tbody>{shown.map((r,i)=><tr key={i} className="border-t border-slate-100"><td className="px-4 py-4"><input type="checkbox"/></td>{columns.map(([key])=><td key={key} className="max-w-[240px] px-4 py-4 text-sm"><span className="block truncate">{key==="status"?<Status>{r[key]}</Status>:key==="name"||key==="title"?<strong className="text-[#0d3568]">{r[key]}</strong>:r[key]}</span></td>)}<td className="px-4 py-4"><div className="flex gap-1"><button onClick={onView} title="View" className="rounded-lg p-2 text-slate-400 hover:bg-blue-50 hover:text-[#1555b6]"><ArrowRight className="h-4 w-4"/></button><button className="rounded-lg p-2 text-slate-400 hover:bg-blue-50 hover:text-[#1555b6]"><Pencil className="h-4 w-4"/></button>{onDelete&&<button onClick={onDelete} className="rounded-lg p-2 text-slate-400 hover:bg-red-50 hover:text-red-600"><Trash2 className="h-4 w-4"/></button>}<button className="rounded-lg p-2 text-slate-400"><MoreHorizontal className="h-4 w-4"/></button></div></td></tr>)}</tbody></table></div><div className="flex flex-col justify-between gap-3 border-t p-4 text-xs text-slate-500 sm:flex-row sm:items-center"><div className="flex items-center gap-2">Rows per page <select className="rounded-lg border bg-white px-2 py-1"><option>10</option><option>25</option></select> · {shown.length} records</div><div className="flex items-center gap-2"><button className="rounded-lg border p-2"><ChevronLeft className="h-4 w-4"/></button><span className="rounded-lg bg-[#1555b6] px-3 py-2 font-bold text-white">1</span><button className="rounded-lg border p-2"><ChevronRight className="h-4 w-4"/></button></div></div></Card>}

export default function AdminPortal(){const {section="overview"}=useParams();const active=titles[section]?section:"overview";const title=titles[active];const nav=useNavigate();const [mobile,setMobile]=useState(false);const [modal,setModal]=useState<string|null>(null);const [notice,setNotice]=useState<string|null>(null);const go=(key:string)=>{nav(key==="overview"?"/portal/administrative/workspace":`/portal/administrative/workspace/${key}`);setMobile(false)};const flash=(s:string)=>{setNotice(s);setTimeout(()=>setNotice(null),2400)};return <main className="min-h-screen bg-[#f3f8fc] font-['Poppins',sans-serif] text-slate-900 lg:grid lg:grid-cols-[286px_1fr]">
  <aside className={`${mobile?"fixed inset-0 z-50 flex":"hidden"} lg:sticky lg:top-0 lg:flex lg:h-screen`}><div className="flex h-full w-[286px] shrink-0 flex-col bg-[#08284e] p-4 text-white"><div className="flex items-center justify-between px-2 py-2"><img src={logo} alt="Simple Lecture" className="h-8 w-auto brightness-0 invert"/><button onClick={()=>setMobile(false)} className="lg:hidden"><X/></button></div><div className="mx-2 mt-5 rounded-2xl bg-gradient-to-br from-[#079a9d] to-[#1555b6] p-4"><div className="flex items-center gap-3"><span className="grid h-10 w-10 place-items-center rounded-xl bg-white/15"><ShieldCheck className="h-5 w-5"/></span><div><p className="text-xs text-white/65">Administration</p><p className="font-bold">Control Center</p></div></div><p className="mt-3 border-t border-white/15 pt-3 text-xs text-white/70">Highest-level institutional visibility</p></div><nav className="mt-5 flex-1 space-y-4 overflow-y-auto px-1 pb-5">{navGroups.map(g=><div key={g.label}><p className="mb-1.5 px-3 text-[10px] font-bold uppercase tracking-[.18em] text-white/35">{g.label}</p><div className="space-y-1">{g.items.map(it=><button key={it.key} onClick={()=>go(it.key)} className={`flex w-full items-center gap-3 rounded-xl px-3 py-2.5 text-left text-sm font-semibold transition ${active===it.key?"bg-white text-[#0d3568]":"text-white/65 hover:bg-white/10 hover:text-white"}`}><it.icon className="h-[18px] w-[18px]"/><span className="flex-1">{it.label}</span>{it.badge&&<span className="rounded-full bg-amber-400 px-2 text-[10px] font-black text-amber-950">{it.badge}</span>}</button>)}</div></div>)}</nav><Link to="/auth" className="flex items-center gap-2 rounded-xl px-3 py-3 text-sm font-semibold text-white/50 hover:bg-white/10 hover:text-white"><ArrowLeft className="h-4 w-4"/>Exit admin preview</Link></div><button onClick={()=>setMobile(false)} className="flex-1 bg-slate-950/55 lg:hidden"/></aside>
  <section className="min-w-0"><header className="sticky top-0 z-30 flex h-[76px] items-center justify-between border-b border-[#d8e8f2] bg-white/95 px-4 backdrop-blur lg:px-7"><div className="flex min-w-0 items-center gap-3"><button onClick={()=>setMobile(true)} className="rounded-xl border p-2.5 lg:hidden"><Menu className="h-5 w-5"/></button><div className="min-w-0"><h1 className="truncate text-lg font-black text-[#0d3568] lg:text-xl">{title[0]}</h1><p className="hidden truncate text-xs text-slate-500 sm:block">{title[1]}</p></div></div><div className="flex items-center gap-2"><button className="relative rounded-xl border p-2.5 text-slate-500"><Bell className="h-5 w-5"/><i className="absolute right-2 top-2 h-2 w-2 rounded-full bg-red-500 ring-2 ring-white"/></button><button onClick={()=>go("profile")} className="hidden items-center gap-3 border-l pl-4 text-left sm:flex"><span className="grid h-10 w-10 place-items-center rounded-xl bg-[#e5f7fa] font-black text-[#087f85]">AD</span><span><strong className="block text-sm">Ananya Desai</strong><small className="text-slate-400">Super Administrator</small></span><ChevronDown className="h-4 w-4 text-slate-400"/></button></div></header>{notice&&<div className="fixed right-5 top-24 z-[70] flex items-center gap-3 rounded-2xl bg-[#0d3568] px-5 py-4 text-sm font-semibold text-white shadow-2xl"><CheckCircle2 className="h-5 w-5 text-teal-300"/>{notice}</div>}<div className="mx-auto max-w-[1600px] p-4 lg:p-7"><AdminContent active={active} go={go} modal={setModal} flash={flash}/></div></section>
  {modal&&<AdminModal type={modal} close={()=>setModal(null)}/>}</main>}

function AdminContent({active,go,modal,flash}:{active:string;go:(s:string)=>void;modal:(s:string)=>void;flash:(s:string)=>void}){switch(active){
  case "overview":return <Dashboard go={go}/>;
  case "students":return <><PageHead eyebrow="Student management" title="1,842 student records" copy="Manage status, course allocation and account access." actions={<div className="flex gap-2"><Secondary><Download className="h-4 w-4"/>Export</Secondary><Primary onClick={()=>go("student-add")}><Plus className="h-4 w-4"/>Add student</Primary></div>}/><DataTable rows={adminStudents} columns={[["id","Student ID"],["name","Student"],["email","Email"],["phone","Phone"],["course","Course"],["batch","Batch"],["joined","Enrolled"],["status","Status"],["lastActive","Last active"]]} onView={()=>go("student-profile")} onDelete={()=>modal("delete-student")}/></>;
  case "student-add":return <PersonForm kind="Student"/>; case "student-profile":return <StudentProfile/>;
  case "faculty":return <><PageHead eyebrow="Faculty management" title="68 faculty members" copy="Teaching assignments, workload and account standing." actions={<Primary onClick={()=>go("faculty-add")}><Plus className="h-4 w-4"/>Add faculty</Primary>}/><DataTable rows={adminFaculty} columns={[["id","Faculty ID"],["name","Faculty"],["email","Email"],["department","Department"],["subjects","Subjects"],["classes","Classes"],["students","Students"],["workload","Workload"],["status","Status"],["lastActive","Last active"]]} onView={()=>go("faculty-profile")} onDelete={()=>modal("delete-faculty")}/></>;
  case "faculty-add":return <PersonForm kind="Faculty"/>; case "faculty-profile":return <FacultyProfile/>;
  case "departments":return <><PageHead eyebrow="Academic structure" title="Departments" copy="Ownership, people and program coverage." actions={<Primary onClick={()=>modal("department")}><Plus className="h-4 w-4"/>Add department</Primary>}/><DataTable rows={departments} columns={[["code","Code"],["name","Department"],["head","Department head"],["faculty","Faculty"],["students","Students"],["courses","Courses"],["status","Status"]]} onView={()=>go("department-details")} onDelete={()=>modal("delete-department")}/></>;
  case "department-details":return <EntityDetail type="Department"/>;
  case "courses":return <><PageHead eyebrow="Academics" title="Course catalog" copy="Programs, ownership, capacity and status." actions={<Primary onClick={()=>modal("course")}><Plus className="h-4 w-4"/>Create course</Primary>}/><DataTable rows={courses} columns={[["code","Code"],["name","Course"],["department","Department"],["duration","Duration"],["students","Students"],["faculty","Faculty"],["subjects","Subjects"],["batches","Batches"],["status","Status"]]} onView={()=>go("course-details")} onDelete={()=>modal("delete-course")}/></>;
  case "course-details":return <EntityDetail type="Course"/>;
  case "subjects":return <><PageHead eyebrow="Curriculum" title="Subject management" copy="Map subjects to courses, semesters and faculty." actions={<Primary onClick={()=>modal("subject")}><Plus className="h-4 w-4"/>Add subject</Primary>}/><DataTable rows={subjects} columns={[["code","Code"],["name","Subject"],["course","Course"],["department","Department"],["faculty","Faculty"],["students","Students"],["semester","Semester"],["status","Status"]]} onDelete={()=>modal("delete-subject")}/></>;
  case "batches":return <><PageHead eyebrow="Class management" title="Batches & groups" copy="Academic year, roster size and teaching assignment." actions={<Primary onClick={()=>modal("batch")}><Plus className="h-4 w-4"/>Create batch</Primary>}/><DataTable rows={batches} columns={[["code","Code"],["name","Batch"],["course","Course"],["year","Academic year"],["students","Students"],["faculty","Faculty"],["start","Start"],["end","End"],["status","Status"]]} onView={()=>go("batch-details")} onDelete={()=>modal("delete-batch")}/></>;
  case "batch-details":return <EntityDetail type="Batch"/>; case "enrollments":return <Enrollments modal={modal}/>; case "timetable":return <Timetable modal={modal}/>;
  case "content":return <><PageHead eyebrow="Content governance" title="Learning content" copy="Inspect videos, documents, lessons and quizzes." actions={<Secondary><Download className="h-4 w-4"/>Content report</Secondary>}/><StatGrid items={[["Videos","1,248",FileText],["Documents","836",FileText],["Lessons","2,914",BookOpen],["Quizzes","486",FileCheck2]]}/><div className="mt-5"><DataTable rows={contentItems} columns={[["title","Content title"],["type","Type"],["course","Course"],["subject","Subject"],["faculty","Faculty"],["created","Created"],["status","Status"]]} onDelete={()=>modal("delete-content")}/></div></>;
  case "assignments":return <><PageHead eyebrow="Learning oversight" title="Assignments" copy="Deadlines, submissions and faculty ownership."/><StatGrid items={[["Total assignments","386",ClipboardList],["Active","68",Activity],["Upcoming","24",Clock3],["Completed","294",CheckCircle2]]}/><div className="mt-5"><DataTable rows={assignments} columns={[["title","Assignment"],["subject","Subject"],["course","Course"],["faculty","Faculty"],["batch","Batch"],["due","Due date"],["submissions","Submitted"],["pending","Pending"],["status","Status"]]} onView={()=>go("assignment-details")} onDelete={()=>modal("delete-assignment")}/></div></>;
  case "assignment-details":return <AssessmentDetail type="Assignment"/>;
  case "exams":return <><PageHead eyebrow="Examination control" title="Exams" copy="Schedule, supervise and review institution-wide assessments." actions={<Primary onClick={()=>modal("exam")}><Plus className="h-4 w-4"/>Schedule exam</Primary>}/><StatGrid items={[["Total exams","124",FileCheck2],["Upcoming","18",Clock3],["Ongoing","3",Activity],["Completed","103",CheckCircle2]]}/><div className="mt-5"><DataTable rows={exams} columns={[["name","Exam"],["course","Course"],["subject","Subject"],["batch","Batch"],["faculty","Faculty"],["date","Date"],["duration","Duration"],["marks","Marks"],["status","Status"]]} onView={()=>go("exam-details")} onDelete={()=>modal("delete-exam")}/></div></>;
  case "exam-details":return <AssessmentDetail type="Exam"/>; case "results":return <Results/>; case "attendance":return <Attendance/>; case "student-progress":return <StudentProgress/>; case "faculty-activity":return <FacultyActivity/>;
  case "announcements":return <Communication kind="Announcement" modal={modal}/>; case "notifications":return <Communication kind="Notification" modal={modal}/>; case "users":return <UsersPage modal={modal}/>; case "roles":return <Roles/>; case "approvals":return <Approvals modal={modal}/>; case "reports":return <Reports flash={flash}/>; case "analytics":return <Analytics/>; case "audit":return <Audit/>; case "settings":return <SettingsPage flash={flash}/>; case "profile":return <AdminProfile/>; default:return null;
}}

function Dashboard({go}:{go:(s:string)=>void}){return <><div className="relative overflow-hidden rounded-3xl bg-gradient-to-r from-[#1555b6] to-[#079a9d] p-6 text-white lg:p-8"><div className="absolute -right-16 -top-28 h-72 w-72 rounded-full border-[60px] border-white/10"/><div className="relative"><p className="flex items-center gap-2 text-xs font-bold uppercase tracking-[.18em] text-white/65"><Sparkles className="h-4 w-4"/>Institution control center</p><h2 className="mt-3 text-3xl font-black lg:text-4xl">Good morning, Ananya.</h2><p className="mt-2 max-w-2xl text-sm leading-6 text-white/75">The LMS is healthy. Two approval requests, three upcoming exams, and six at-risk students need administrative attention.</p><div className="mt-6 flex flex-wrap gap-2"><button onClick={()=>go("approvals")} className="rounded-xl bg-white px-4 py-2.5 text-sm font-bold text-[#1555b6]">Review approvals</button><button onClick={()=>go("analytics")} className="rounded-xl border border-white/30 bg-white/10 px-4 py-2.5 text-sm font-bold">Open analytics</button></div></div></div><div className="mt-5"><StatGrid items={[["Total students","1,842",Users,"+46 this month"],["Active faculty","64",GraduationCap,"94% active"],["Courses","14",BookOpen,"4 departments"],["Upcoming exams","18",FileCheck2,"Next: 24 Aug"]]}/></div><div className="mt-5 grid gap-5 xl:grid-cols-[1.25fr_.75fr]"><Card className="p-6"><div className="flex justify-between"><div><h3 className="font-black text-[#0d3568]">Institution health</h3><p className="text-xs text-slate-500">Academic and operational indicators</p></div><Status>Healthy</Status></div><div className="mt-6 grid gap-6 sm:grid-cols-2">{[["Overall attendance",88],["Average performance",76],["Course completion",72],["Faculty workload balance",84]].map(([l,v])=><div key={l as string}><div className="mb-2 flex justify-between text-sm"><span className="text-slate-500">{l as string}</span><strong>{v}%</strong></div><Progress value={v as number}/></div>)}</div><div className="mt-6 grid gap-3 sm:grid-cols-3">{[["Present today","1,618","teal"],["Absent today","188","amber"],["Need attention","36","red"]].map(([l,v,c])=><div key={l} className="rounded-xl bg-slate-50 p-4"><p className="text-xs text-slate-500">{l}</p><p className={`mt-1 text-2xl font-black ${c==="red"?"text-red-600":c==="amber"?"text-amber-600":"text-[#079a9d]"}`}>{v}</p></div>)}</div></Card><Card className="p-6"><div className="flex justify-between"><div><h3 className="font-black text-[#0d3568]">Quick actions</h3><p className="text-xs text-slate-500">Common administrative work</p></div></div><div className="mt-5 grid gap-2">{[["Add student","student-add",UserPlus],["Add faculty","faculty-add",GraduationCap],["Create course","courses",BookOpen],["Create batch","batches",Building2],["Schedule exam","exams",FileCheck2],["Announcement","announcements",MessageSquare]].map(([l,k,Icon])=><button key={l as string} onClick={()=>go(k as string)} className="flex items-center justify-between rounded-xl border border-slate-100 p-3 text-left text-sm font-bold hover:border-[#1555b6]"><span className="flex items-center gap-3"><Icon className="h-4 w-4 text-[#1555b6]"/>{l as string}</span><ArrowRight className="h-4 w-4 text-slate-400"/></button>)}</div></Card></div><div className="mt-5 grid gap-5 lg:grid-cols-2"><Card className="p-6"><h3 className="font-black text-[#0d3568]">Students by course</h3><MiniBars labels={[["B.Sc Computer Science",486],["B.Com",392],["PUC Science",318],["PUC Commerce",236]]}/></Card><Card className="p-6"><h3 className="font-black text-[#0d3568]">Recent activity</h3><div className="mt-5 space-y-3">{auditLogs.slice(0,4).map(a=><div key={a.time} className="flex gap-3 rounded-xl bg-slate-50 p-3"><span className="grid h-9 w-9 place-items-center rounded-xl bg-blue-100 text-blue-700"><Activity className="h-4 w-4"/></span><div><p className="text-sm font-bold">{a.action}</p><p className="text-xs text-slate-400">{a.user} · {a.time}</p></div></div>)}</div></Card></div></>}

function MiniBars({labels}:{labels:[string,number][]}){const max=Math.max(...labels.map(x=>x[1]));return <div className="mt-5 space-y-4">{labels.map(([l,v])=><div key={l}><div className="mb-1.5 flex justify-between text-sm"><span className="text-slate-600">{l}</span><strong>{v}</strong></div><Progress value={v/max*100}/></div>)}</div>}
