function Enrollments({modal}:{modal:(s:string)=>void}){const rows=adminStudents.map(s=>({name:s.name,id:s.id,course:s.course,batch:s.batch,joined:s.joined,status:s.status}));return <><PageHead eyebrow="Student allocation" title="1,796 active enrollments" copy="Course and batch membership across the institution." actions={<Primary onClick={()=>modal("enrollment")}><Plus className="h-4 w-4"/>New enrollment</Primary>}/><StatGrid items={[["Total enrollments","1,842",ClipboardCheck],["New this month","46",UserPlus],["Active","1,796",CheckCircle2],["Pending","22",Clock3]]}/><div className="mt-5"><DataTable rows={rows} columns={[["name","Student"],["id","Student ID"],["course","Course"],["batch","Batch"],["joined","Enrollment date"],["status","Status"]]} onDelete={()=>modal("delete-enrollment")}/></div></>}
