function Results(){const rows=adminStudents.map(s=>({name:s.name,exam:"Unit Test 01",subject:"Classical Mechanics",marks:`${s.performance}/100`,percentage:s.performance,grade:s.performance>85?"A":s.performance>70?"B":"C",status:s.performance>=60?"Passed":"Failed"}));return <><PageHead eyebrow="Academic outcomes" title="Results analysis" copy="Filter by course, batch, subject, exam or student."/><StatGrid items={[["Students appeared","1,624",Users],["Passed","1,438",CheckCircle2],["Failed","186",AlertCircle],["Average score","76%",BarChart3]]}/><div className="mt-5 grid gap-5 lg:grid-cols-3"><Card className="p-5 lg:col-span-2"><h3 className="font-black text-[#0d3568]">Grade distribution</h3><MiniBars labels={[["A grade",426],["B grade",582],["C grade",430],["Below pass",186]]}/></Card><Card className="p-5"><h3 className="font-black text-[#0d3568]">Pass vs fail</h3><div className="mx-auto mt-7 grid h-40 w-40 place-items-center rounded-full border-[18px] border-[#1555b6] border-r-red-400"><div className="text-center"><p className="text-3xl font-black">89%</p><p className="text-xs text-slate-400">Pass rate</p></div></div></Card></div><div className="mt-5"><DataTable rows={rows} columns={[["name","Student"],["exam","Exam"],["subject","Subject"],["marks","Marks"],["percentage","Percentage"],["grade","Grade"],["status","Result"]]}/></div></>}
