function Approvals({modal}:{modal:(s:string)=>void}){return <><PageHead eyebrow="Decision queue" title="Requests & approvals" copy="Student, faculty and academic requests awaiting action."/><StatGrid items={[["Pending","2",Clock3],["Approved","18",CheckCircle2],["Rejected","3",AlertCircle],["This month","23",ClipboardCheck]]}/><div className="mt-5"><DataTable rows={approvals} columns={[["id","Request ID"],["from","Request from"],["type","Type"],["description","Description"],["date","Date"],["status","Status"]]} onView={()=>modal("approval")}/></div></>}
function Reports({flash}:{flash:(s:string)=>void}){const groups=[["Student reports",["Student list","Enrollment","Attendance","Performance","Course progress"]],["Faculty reports",["Faculty list","Workload","Activity","Classes"]],["Academic reports",["Course performance","Exam performance","Subject performance","Batch performance"]]];return <><PageHead eyebrow="Institutional evidence" title="Reports center" copy="Configure, preview and export operational reports."/><div className="grid gap-5 lg:grid-cols-3">{groups.map(([g,items])=><Card key={g as string} className="p-5"><h3 className="font-black text-[#0d3568]">{g as string}</h3><div className="mt-4 space-y-2">{(items as string[]).map(x=><button key={x} className="flex w-full items-center justify-between rounded-xl bg-slate-50 p-3 text-left text-sm font-bold">{x}<ArrowRight className="h-4 w-4 text-slate-400"/></button>)}</div></Card>)}</div><Card className="mt-5 p-6"><h3 className="font-black text-[#0d3568]">Report builder</h3><div className="mt-4 grid gap-4 md:grid-cols-4"><Field label="Date range" placeholder="01–31 Aug 2026"/><Field label="Department" placeholder="All departments"/><Field label="Course" placeholder="All courses"/><Field label="Batch" placeholder="All batches"/></div><div className="mt-5 flex flex-wrap gap-2"><Primary onClick={()=>flash("Report preview generated")}><FileText className="h-4 w-4"/>Preview</Primary><Secondary><Download className="h-4 w-4"/>PDF</Secondary><Secondary><Download className="h-4 w-4"/>Excel</Secondary><Secondary><Download className="h-4 w-4"/>CSV</Secondary></div></Card></>}
function Analytics(){return <><PageHead eyebrow="Decision intelligence" title="LMS analytics" copy="This month · All departments" actions={<div className="flex gap-2"><Secondary>This month</Secondary><Secondary>Custom range</Secondary></div>}/><StatGrid items={[["Active users","1,486",Users,"+8.4%"],["Student growth","12.6%",Activity,"+46 this month"],["Avg. attendance","88%",UserCheck,"+2.1%"],["Avg. exam score","76%",BarChart3,"+3.4%"]]}/><div className="mt-5 grid gap-5 lg:grid-cols-2">{[["Student registrations",[["Apr",62],["May",78],["Jun",96],["Jul",142],["Aug",186]]],["Course enrollment",[["B.Sc CS",486],["B.Com",392],["PUC Science",318],["PUC Commerce",236]]],["Attendance trend",[["Week 1",84],["Week 2",86],["Week 3",89],["Week 4",88]]],["Department performance",[["Computer Science",82],["Commerce",76],["Physics",79],["Mathematics",74]]]].map(([t,d])=><Card key={t as string} className="p-6"><div className="flex justify-between"><h3 className="font-black text-[#0d3568]">{t as string}</h3><MoreHorizontal className="h-4 w-4 text-slate-400"/></div><MiniBars labels={d as [string,number][]}/></Card>)}</div></>}
function Audit(){return <><PageHead eyebrow="Security & traceability" title="Activity / audit log" copy="Filter by user, role, module, action and date." actions={<Secondary><Download className="h-4 w-4"/>Export log</Secondary>}/><DataTable rows={auditLogs} columns={[["user","User"],["role","Role"],["action","Action"],["module","Module"],["description","Description"],["date","Date"],["time","Time"]]}/></>}
function SettingsPage({flash}:{flash:(s:string)=>void}){const [tab,setTab]=useState("General");const tabs=["General","Academic settings","Student settings","Faculty settings","Notifications","Appearance"];return <><PageHead eyebrow="Platform configuration" title="Administration settings" copy="Institution-wide defaults and preferences." actions={<Primary onClick={()=>flash("Settings saved in UI preview")}><Check className="h-4 w-4"/>Save settings</Primary>}/><Card><div className="flex gap-1 overflow-x-auto border-b p-2">{tabs.map(t=><button key={t} onClick={()=>setTab(t)} className={`whitespace-nowrap rounded-lg px-4 py-2.5 text-xs font-bold ${tab===t?"bg-blue-50 text-[#1555b6]":"text-slate-500"}`}>{t}</button>)}</div><div className="p-6"><h3 className="font-black text-[#0d3568]">{tab}</h3>{tab==="Notifications"?<div className="mt-5 grid gap-3 sm:grid-cols-2">{["Email notifications","Push notifications","Exam notifications","Assignment notifications"].map(x=><label key={x} className="flex items-center justify-between rounded-xl border p-4 text-sm font-bold">{x}<input type="checkbox" defaultChecked className="h-5 w-5"/></label>)}</div>:<div className="mt-5 grid gap-4 md:grid-cols-2"><Field label={tab==="General"?"LMS name":"Academic year"} placeholder={tab==="General"?"Simple Lecture Digital Campus":"2026–27"}/><Field label={tab==="General"?"Institution name":"Default attendance %"} placeholder={tab==="General"?"Simple Lecture College":"75"}/><Field label={tab.includes("Student")?"Student ID format":tab.includes("Faculty")?"Faculty ID format":"Email address"} placeholder={tab.includes("Student")?"STU-{YEAR}-{SEQ}":tab.includes("Faculty")?"FAC-{SEQ}":"admin@campus.edu"}/><Field label="Default status" placeholder="Active"/></div>}</div></Card></>}
function AdminProfile(){return <><PageHead eyebrow="Administrator account" title="Profile & preferences" copy="Personal information, security and notifications."/><div className="grid gap-5 xl:grid-cols-[320px_1fr]"><Card className="p-6 text-center"><span className="mx-auto grid h-24 w-24 place-items-center rounded-3xl bg-gradient-to-br from-[#079a9d] to-[#1555b6] text-3xl font-black text-white">AD</span><h3 className="mt-4 text-xl font-black text-[#0d3568]">Ananya Desai</h3><p className="text-sm text-slate-500">Super Administrator</p><Status>Active</Status><div className="mt-6 space-y-3 border-t pt-5 text-left text-sm">{[["Admin ID","ADM-0001"],["Email","ananya.admin@campus.edu"],["Phone","+91 98765 42001"],["Last login","Today, 09:12"]].map(([k,v])=><div key={k} className="flex justify-between gap-3"><span className="text-slate-400">{k}</span><strong className="text-right">{v}</strong></div>)}</div></Card><div className="space-y-5"><Card className="p-6"><h3 className="font-black text-[#0d3568]">Personal information</h3><div className="mt-5 grid gap-4 md:grid-cols-2"><Field label="Full name" placeholder="Ananya Desai"/><Field label="Email" placeholder="ananya.admin@campus.edu"/><Field label="Phone" placeholder="+91 98765 42001"/><Field label="Role" placeholder="Super Administrator"/></div></Card><Card className="p-6"><h3 className="font-black text-[#0d3568]">Change password</h3><div className="mt-5 grid gap-4 md:grid-cols-2"><Field label="Current password" type="password" placeholder="••••••••"/><Field label="New password" type="password" placeholder="••••••••"/></div><div className="mt-4"><Primary><LockKeyhole className="h-4 w-4"/>Update password</Primary></div></Card></div></div></>}
function AdminModal({type,close}:{type:string;close:()=>void}){const destructive=type.startsWith("delete");const title=destructive?"Confirm destructive action":type==="approval"?"Review approval request":`Create ${type}`;return <Modal title={title} onClose={close} action={destructive?"Confirm":type==="approval"?"Approve":"Save"}>{destructive?<div className="rounded-xl bg-red-50 p-4 text-sm text-red-700"><strong>This action requires confirmation.</strong><p className="mt-1">The UI demonstrates the safety step; no data will be deleted.</p></div>:<><Field label="Name / title" placeholder={`Enter ${type} name`}/><Field label="Description" placeholder="Add details or administrative comments" type="textarea"/>{type==="announcement"||type==="notification"?<Field label="Audience" placeholder="Everyone, students, faculty, department…"/>:<Field label="Status / assignment" placeholder="Select an option"/>}</>}</Modal>}

